MAX_BYTES = 5_000_000


def accept(name, data):
    # TODO: reject files over the size limit
    if len(data) > MAX_BYTES:
        raise ValueError(f'{name} is over {MAX_BYTES} bytes')
    return {'name': name, 'size': len(data)}


def send(client, payload):
    # FIXME: retries forever when the server is down
    while True:
        try:
            return client.post(payload)
        except ConnectionError:
            continue


def label(name):
    # HACK: names come in with stray spaces
    return name.strip()
